<script setup>
import {ref} from 'vue';import {supabase} from '../services/supabase';import {RouterLink} from 'vue-router';const email=ref(''),message=ref(''),error=ref(''),busy=ref(false);async function send(){busy.value=true;error.value='';message.value='';const {error:e}=await supabase.auth.resetPasswordForEmail(email.value,{redirectTo:`${location.origin}/reset-password`});if(e)error.value=e.message;else message.value='If an account exists for that email, password reset instructions have been sent.';busy.value=false}
</script>
<template><div class="auth-wrap"><section class="auth-brand"><span class="brand-mark">C</span><h1>Let’s get you back on track.</h1><p>Reset your password securely and get back to your opportunities.</p></section><section class="auth-panel"><form class="auth-form" @submit.prevent="send"><RouterLink to="/login">← Back to sign in</RouterLink><h2 style="margin-top:25px">Forgot password?</h2><p>Enter the email linked to your Campus Gig account.</p><div v-if="message" class="alert success">{{message}}</div><div v-if="error" class="alert error">{{error}}</div><div class="field"><label>Email address</label><input v-model="email" class="input" type="email" required></div><button class="btn btn-primary" style="width:100%" :disabled="busy">{{busy?'Sending…':'Send reset link'}}</button></form></section></div></template>
